// Extract message data
const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();

// Get user info
const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
const messageId = originalMsg.message_id;

// Handle callback queries
let answerCallback = null;
if (messageType === 'callback_query') {
    text = payload.data || payload.callback_data || payload.content || 
           (originalMsg.data ? originalMsg.data : '') || '';

    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) {
            chatId = originalMsg.message.chat.id;
        } else if (originalMsg.chat) {
            chatId = originalMsg.chat.id;
        }
    }

    if (originalMsg.from) {
        userId = originalMsg.from.id;
    }

    const callbackQueryId = payload.callback_query_id || payload.id || 
                            (originalMsg.id ? originalMsg.id.toString() : null) ||
                            (originalMsg.query_id ? originalMsg.query_id.toString() : null);

    if (callbackQueryId) {
        answerCallback = {
            payload: {
                callback_query_id: callbackQueryId,
                text: '',
                show_alert: false
            },
            topic: 'answerCallbackQuery'
        };
    }
}

// Check if it's a gate command
if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    return [null, answerCallback].filter(m => m !== null);
}

// Store chat ID for gate notifications
if (!flow.get('gate_telegram_chat_ids')) {
    flow.set('gate_telegram_chat_ids', []);
}
const chatIds = flow.get('gate_telegram_chat_ids');
if (!chatIds.includes(chatId)) {
    chatIds.push(chatId);
    flow.set('gate_telegram_chat_ids', chatIds);
}

// Parse command
const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1);

// Only handle gate-specific commands
if (!command.startsWith('/gate')) {
    return [null, answerCallback].filter(m => m !== null);
}

// Store telegram data
msg.telegram = {
    chatId: chatId,
    userId: userId,
    messageId: messageId,
    command: command,
    args: args,
    originalText: text
};

// Route to appropriate handler
if (command === '/gate_open' || command === '/gate') {
    msg.topic = 'gate_open';
} else if (command === '/gate_status') {
    msg.topic = 'gate_status';
} else if (command === '/gate_help') {
    msg.topic = 'gate_help';
} else {
    msg.topic = 'gate_unknown';
}

return [msg, answerCallback].filter(m => m !== null);

if (msg.payload && msg.payload.callback_query_id) {
    msg.payload = {
        callback_query_id: msg.payload.callback_query_id,
        text: msg.payload.text || '',
        show_alert: msg.payload.show_alert || false
    };
    msg.topic = 'answerCallbackQuery';
    return msg;
}
return null;

// Create MQTT command
const timestamp = new Date().toISOString();
const requestId = `telegram-gate-${Date.now()}`;

const telegramData = msg.telegram;

// Create MQTT message to trigger gate
msg.payload = 'ON';
msg.topic = 'MainGate/CMD/Relay2';
msg.telegram = telegramData;
msg.telegram.requestId = requestId;

// Log command
const command = {
    action: 'relay2_toggle',
    value: 'ON',
    timestamp: timestamp,
    request_id: requestId,
    source: 'telegram',
    user_id: telegramData.userId
};

flow.set('lastCommand', command);

let history = flow.get('commandHistory') || [];
history.unshift(command);
if (history.length > 10) history = history.slice(0, 10);
flow.set('commandHistory', history);

// Create confirmation message
const confirmationMsg = {
    ...msg,
    payload: {
        chatId: telegramData.chatId,
        type: 'message',
        content: `🚪 Opening Main Gate...\n\nRelay 2 activated (1 second pulse)\nRequest ID: ${requestId}`,
        parse_mode: 'Markdown'
    },
    topic: 'send'
};

// Send both MQTT command and Telegram confirmation
return [msg, confirmationMsg];

// Get gate state from flow context
const gateState = flow.get('gate_state') || {};
const mainGate = gateState.mainGate || {};

let statusText = '🚪 *Main Gate Status*\n\n';

// Power status
const powerStatus = mainGate.power || 'UNKNOWN';
const powerEmoji = powerStatus === 'MAINS' ? '🔌' : (powerStatus === 'BATTERY' ? '🔋' : '❓');
statusText += `${powerEmoji} *Power*: ${powerStatus}\n\n`;

// Relays
statusText += '*Relays:*\n';
for (let i = 1; i <= 4; i++) {
    const relayStatus = mainGate[`relay${i}`] || 'UNKNOWN';
    const relayEmoji = relayStatus === 'ON' ? '🟢' : (relayStatus === 'OFF' ? '⚫' : '❓');
    statusText += `${relayEmoji} Relay ${i}: ${relayStatus}\n`;
}

// Mains and Keypad
const mainsStatus = mainGate.mains || 'UNKNOWN';
const mainsEmoji = mainsStatus === 'ON' ? '🔌' : '⚫';
statusText += `\n${mainsEmoji} *Mains*: ${mainsStatus}\n`;

const keypadStatus = mainGate.keypad || 'UNKNOWN';
const keypadEmoji = keypadStatus === 'CONNECTED' ? '🔢' : '❌';
statusText += `${keypadEmoji} *Keypad*: ${keypadStatus}\n`;

// Last update
if (mainGate.lastUpdate) {
    const lastUpdate = new Date(mainGate.lastUpdate).toLocaleString('ro-RO');
    statusText += `\n🕐 Last update: ${lastUpdate}`;
}

// Last command
const lastCommand = flow.get('lastCommand');
if (lastCommand) {
    const cmdTime = new Date(lastCommand.timestamp).toLocaleString('ro-RO');
    statusText += `\n\n*Last Command:*\n${lastCommand.action} at ${cmdTime}`;
}

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: statusText,
    parse_mode: 'Markdown'
};
msg.topic = 'send';

return msg;

const helpText = `🚪 *Gate Control Bot*\n\n` +
    `*Available Commands:*\n\n` +
    `🚪 /gate_open or /gate\n` +
    `   Open the main gate (Relay 2)\n\n` +
    `📊 /gate_status\n` +
    `   Get gate status and power info\n\n` +
    `❓ /gate_help\n` +
    `   Show this help message\n\n` +
    `*Features:*\n` +
    `• Automatic power status notifications\n` +
    `• Real-time relay monitoring\n` +
    `• Keypad connectivity tracking\n` +
    `• Command history logging\n\n` +
    `*Quick Actions:*\n` +
    `Use the buttons below:`;

const inlineKeyboard = {
    inline_keyboard: [
        [
            { text: '🚪 Open Main Gate', callback_data: '/gate_open' }
        ],
        [
            { text: '📊 Gate Status', callback_data: '/gate_status' },
            { text: '❓ Help', callback_data: '/gate_help' }
        ]
    ]
};

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: helpText,
    parse_mode: 'Markdown',
    options: {
        reply_markup: JSON.stringify(inlineKeyboard)
    }
};
msg.topic = 'send';

return msg;

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: `❓ Unknown gate command: ${msg.telegram.originalText}\n\nType /gate_help for available commands.`
};
msg.topic = 'send';

return msg;

const chatIds = flow.get('gate_telegram_chat_ids') || [];
if (chatIds.length === 0) {
    return null;
}

const powerStatus = msg.payload;
const powerEmoji = powerStatus === 'MAINS' ? '🔌' : (powerStatus === 'BATTERY' ? '🔋' : '⚠️');

const notificationText = `${powerEmoji} *Main Gate Power Status Changed*\n\n` +
    `New Status: *${powerStatus}*\n` +
    `Time: ${new Date().toLocaleString('ro-RO')}`;

// Send to all registered chats
return chatIds.map(chatId => ({
    payload: {
        chatId: chatId,
        type: 'message',
        content: notificationText,
        parse_mode: 'Markdown'
    }
}));

// Update gate state in context
let state = flow.get('gate_state') || { mainGate: {} };
if (!state.mainGate) state.mainGate = {};

// Update relay 2 status (main gate control)
state.mainGate.relay2 = msg.payload;
state.mainGate.lastUpdate = new Date().toISOString();

flow.set('gate_state', state);

return null; // Don't send notification for relay status (too frequent)

// Update gate state in context
let state = flow.get('gate_state') || { mainGate: {} };
if (!state.mainGate) state.mainGate = {};

state.mainGate.mains = msg.payload;
state.mainGate.lastUpdate = new Date().toISOString();

flow.set('gate_state', state);

return null;

// Update gate state in context
let state = flow.get('gate_state') || { mainGate: {} };
if (!state.mainGate) state.mainGate = {};

state.mainGate.keypad = msg.payload;
state.mainGate.lastUpdate = new Date().toISOString();

flow.set('gate_state', state);

return null;
